var seScripts=[],seCurrentId=null,seDirty=false,seAutoTimer=null,seDragEl=null;var SE_TEMPLATES={coldcall:{name:'Cold Call Script',type:'coldcall',steps:[{title:'Opening (0:00-0:15)',body:'Hey [Name], this is [Your name] from AgentNav. Quick question - we built a platform for health brokers: ACA and STM quoting, full CRM, SMS, and Renewal Autopilot that automates your entire OEP. Worth two minutes?'},{title:'Earn the minute (0:15-0:45)',body:'What does your OEP process look like right now? Running it manually or do you have something in place?'},{title:'Connect pain to feature (0:45-1:30)',body:'[Repeat back what they said.] That is exactly the problem we solve. [Name one specific feature that addresses their pain.]'},{title:'Soft pitch (1:30-2:00)',body:'AgentNav is the only platform built for health brokers - ACA quoting, HealthSherpa, Renewal Autopilot, CRM, SMS, all in one place. Starts at $79 per month.'},{title:'Close for meeting (2:00-2:30)',body:'I would love to show you a 15-minute demo. Do you have time Thursday or Friday?'}]},discovery:{name:'Discovery Call Script',type:'discovery',steps:[{title:'Set the agenda',body:'Thanks for making time. I want to spend most of this call learning about how you are set up right now. Then if I think AgentNav could help, I will be honest about that. Sound good?'},{title:'Current setup',body:'Walk me through your agency. How big is your team? What tools for quoting, CRM, SMS, enrollment? How are you managing renewals?'},{title:'Find the pain',body:'What does your OEP look like? How many clients are you manually reaching out to in November? How many slip through?'},{title:'Qualify',body:'What percentage of your book is ACA vs other lines? Do you use HealthSherpa or EDE? Looking to grow the team this year?'},{title:'Set up the demo',body:'Based on what you told me, here is what I want to show you: [Name 2-3 specific features]. Does that sound right?'}]},demo:{name:'Demo Meeting Script',type:'demo',steps:[{title:'Confirm discovery',body:'Before I share my screen - last time you mentioned [pain point]. Is that still the main thing you want to see solved today?'},{title:'Client record',body:'This is where a client lives - everything in one place. Medical history, Rx, FPL tracking, policy history, SMS thread, calendar.'},{title:'Renewal Autopilot',body:'Every renewal client has a status. For each one with Autopilot on, the system sends the campaign, collects preferences, and generates a new quote. You just review and approve.'},{title:'Quoting',body:'ACA, STM, Life, Ancillary, Indemnity - all quoted side by side. Pull from HealthSherpa or EDE directly. One-click to send the proposal.'},{title:'Close',body:'What questions do you have? [Pause.] Based on what you saw today, what would need to be true for this to be a yes?'}]},objections:{name:'Objection Handling',type:'objections',steps:[{title:'"Too expensive"',body:'What are you paying right now for CRM, quoting, SMS, and enrollment combined? Most agents are at $200-400 per month. AgentNav replaces all of it for $79.'},{title:'"Need to think about it"',body:'Totally fair. What specifically do you want to think through? Price, timing, or something you want to verify?'},{title:'"Happy with what we have"',body:'What does your OEP process look like? How many clients did you lose last November because they fell through? That is what Renewal Autopilot eliminates.'},{title:'"Need to talk to my partner"',body:'Of course. Can we get them on a quick call together this week?'},{title:'"Not the right time"',body:'When is? Agents who switch before OEP go in with Autopilot already configured.'}]}};var SE_GROUPS=[{label:'Before The Call',types:['coldcall','discovery']},{label:'On The Call',types:['demo','closing','onboarding']},{label:'Reference',types:['objections','talktracks']},{label:'My Scripts',types:['custom']}];var SE_TYPE_LABELS={coldcall:'Cold Call',discovery:'Discovery',demo:'Demo Meeting',closing:'Closing',onboarding:'Onboarding',objections:'Objections',talktracks:'Talk Track',custom:'Custom'};var SE_SUGGESTIONS={coldcall:['Rewrite step 1 to sound more natural','Make the pitch under 30 words','Add a line for when they say they are happy with their setup'],discovery:['Write 3 follow-up questions for step 2','Add a question about how they handle renewals','Make the agenda line more conversational'],demo:['Rewrite Renewal Autopilot step for a solo agent','Add a line for when they compare to EZLynx','Write a closing line that creates urgency'],objections:['Write a response for when they bring up HawkSoft','Make the price objection shorter','Add a response for not ready until after OEP'],custom:['Improve the flow of this script','Make this more conversational','Suggest a stronger opening line']};function seLoad(){try{seScripts=JSON.parse(localStorage.getItem('se2')||'[]')}catch(e){seScripts=[]}}
function sePersist(){localStorage.setItem('se2',JSON.stringify(seScripts))}
function seRenderLib(){
var el=document.getElementById('se-lib-list');
if(!el)return;
el.innerHTML='';

// ── PREBUILT TEMPLATES SECTION (always shown at top) ──
var prebuiltDiv=document.createElement('div');
prebuiltDiv.style.cssText='padding-bottom:4px;border-bottom:1px solid #2a2a38;margin-bottom:4px;';
var prebuiltLbl=document.createElement('div');
prebuiltLbl.style.cssText='font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#6366f1;padding:10px 14px 6px;';
prebuiltLbl.textContent='📋 Prebuilt Templates';
prebuiltDiv.appendChild(prebuiltLbl);

Object.keys(SE_TEMPLATES).forEach(function(k){
  var t=SE_TEMPLATES[k];
  var alreadyLoaded=seScripts.some(function(s){return s._tpl===k;});
  var btn=document.createElement('div');
  btn.style.cssText='display:flex;align-items:center;cursor:pointer;padding:7px 14px;font-size:12px;color:'+(alreadyLoaded?'#4a4a5a':'#c7d2fe')+';border-left:3px solid transparent;';
  btn.innerHTML=(alreadyLoaded?'✓ ':'+ ')+t.name;
  if(!alreadyLoaded){
    btn.onmouseover=function(){this.style.background='#1e1e2e';this.style.borderLeftColor='#6366f1';};
    btn.onmouseout=function(){this.style.background='';this.style.borderLeftColor='transparent';};
    btn.onclick=function(){seLoadTemplate(k);};
  }
  prebuiltDiv.appendChild(btn);
});
el.appendChild(prebuiltDiv);

// ── MY SCRIPTS SECTION ──
SE_GROUPS.forEach(function(g){
  var inGrp=seScripts.filter(function(s){return g.types.indexOf(s.type)>=0;});
  if(!inGrp.length)return;
  var grp=document.createElement('div');grp.style.cssText='padding-bottom:4px;';
  var lbl=document.createElement('div');lbl.style.cssText='font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#52525b;padding:10px 14px 4px;';lbl.textContent=g.label;
  grp.appendChild(lbl);
  inGrp.forEach(function(s){
    var item=document.createElement('div');item.style.cssText='display:flex;align-items:center;cursor:pointer;'+(seCurrentId===s.id?'background:#2a2a38;':'');
    var inner=document.createElement('div');inner.style.cssText='flex:1;padding:7px 14px;font-size:12.5px;color:'+(seCurrentId===s.id?'#6366f1':'#a1a1aa')+';overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border-left:3px solid '+(seCurrentId===s.id?'#6366f1':'transparent')+';font-weight:'+(seCurrentId===s.id?'600':'400')+';';inner.textContent=s.name||'Untitled';
    var del=document.createElement('button');del.style.cssText='padding:7px 8px;background:none;border:none;cursor:pointer;color:#52525b;font-size:11px;flex-shrink:0;';del.textContent='x';del.title='Delete';
    del.onclick=function(e){e.stopPropagation();seDelById(s.id);};
    item.appendChild(inner);item.appendChild(del);
    item.onclick=function(){seOpenScript(s.id);};
    grp.appendChild(item);
  });
  el.appendChild(grp);
});

// My Scripts empty state
var myScripts=seScripts.filter(function(s){return s.type==='custom';});
if(seScripts.length===0){
  var note=document.createElement('div');note.style.cssText='padding:12px 14px;font-size:11px;color:#4a4a5a;font-style:italic;';note.textContent='Load a template or create a new script.';el.appendChild(note);
}
}
function seOpenScript(id){if(seDirty&&!confirm('Unsaved changes. Discard?'))return;seCurrentId=id;seDirty=false;var s=seScripts.find(function(x){return x.id===id});if(!s)return;seShowEditor(s);seRenderLib();seUpdateAI(s);}
function seNewScript(){var id='s'+Date.now();var s={id:id,name:'New Script',type:'custom',steps:[{title:'Step 1',body:''}]};seScripts.push(s);sePersist();seRenderLib();setTimeout(function(){seOpenScript(id);var n=document.getElementById('se-script-name');if(n){n.focus();n.select()}},10);}
function seLoadTemplate(k){var t=SE_TEMPLATES[k];if(!t)return;var id='s'+Date.now();var s={id:id,name:t.name,type:t.type,_tpl:k,steps:t.steps.map(function(st){return{title:st.title,body:st.body}})};seScripts.push(s);sePersist();seRenderLib();seOpenScript(id);}
function seDelById(id){if(!confirm('Delete this script?'))return;seScripts=seScripts.filter(function(s){return s.id!==id});if(seCurrentId===id){seCurrentId=null;seDirty=false;seShowEmpty()}
sePersist();seRenderLib();}
function seDeleteScript(){if(seCurrentId)seDelById(seCurrentId)}
function seShowEditor(s){var ew=document.getElementById('se-editor-wrap');var emp=document.getElementById('se-empty-wrap');if(ew){ew.style.display='flex';ew.style.flex='1';ew.style.flexDirection='column';ew.style.overflow='hidden';}
if(emp)emp.style.display='none';var n=document.getElementById('se-script-name');var t=document.getElementById('se-script-type');if(n)n.value=s.name||'';if(t)t.value=s.type||'custom';seRenderSteps(s.steps||[]);seUpdateCount(s.steps||[]);var st=document.getElementById('se-save-status');if(st)st.textContent='';}
function seShowEmpty(){var ew=document.getElementById('se-editor-wrap');var emp=document.getElementById('se-empty-wrap');if(ew)ew.style.display='none';if(emp){emp.style.display='flex';emp.style.flex='1';}}
function seRenderSteps(steps){var list=document.getElementById('se-steps-list');if(!list)return;list.innerHTML='';steps.forEach(function(st,i){list.appendChild(seMakeStep(st,i))});}
function seMakeStep(st,idx){var div=document.createElement('div');div.style.cssText='background:#f8f8fa;border:1.5px solid #e4e4e7;border-radius:10px;overflow:hidden;';div.draggable=true;var head=document.createElement('div');head.style.cssText='display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid #e4e4e7;background:#fff;';var num=document.createElement('div');num.style.cssText='width:22px;height:22px;border-radius:50%;background:#6366f1;color:#fff;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;';num.textContent=idx+1;var ti=document.createElement('input');ti.type='text';ti.value=st.title||'';ti.placeholder='Step name...';ti.style.cssText='flex:1;border:none;background:none;font-size:13px;font-weight:600;color:#09090b;font-family:inherit;outline:none;';ti.oninput=seMarkDirty;var drag=document.createElement('span');drag.textContent=':::';drag.style.cssText='cursor:grab;color:#d4d4d8;font-size:14px;padding:0 2px;';var del=document.createElement('button');del.textContent='x';del.style.cssText='background:none;border:none;color:#d4d4d8;font-size:12px;cursor:pointer;padding:2px 4px;border-radius:3px;';del.onclick=function(){div.remove();seRenumber();seMarkDirty()};head.append(num,ti,drag,del);var ta=document.createElement('textarea');ta.value=st.body||'';ta.placeholder='Write this step...';ta.style.cssText='width:100%;min-height:80px;border:none;background:none;padding:10px 12px;font-size:13px;color:#52525b;font-family:inherit;resize:vertical;outline:none;line-height:1.65;box-sizing:border-box;';ta.oninput=seMarkDirty;div.append(head,ta);div.addEventListener('dragstart',function(e){e.dataTransfer.effectAllowed='move';div.style.opacity='.4';seDragEl=div});div.addEventListener('dragend',function(){div.style.opacity='';seDragEl=null;seRenumber();seMarkDirty()});div.addEventListener('dragover',function(e){e.preventDefault();if(seDragEl&&seDragEl!==div){var items=Array.from(div.parentNode.children);if(items.indexOf(seDragEl)<items.indexOf(div))div.parentNode.insertBefore(seDragEl,div.nextSibling);else div.parentNode.insertBefore(seDragEl,div)}});return div;}
function seRenumber(){var list=document.getElementById('se-steps-list');if(!list)return;list.querySelectorAll('div>div:first-child>div:first-child').forEach(function(num,i){if(num&&!isNaN(parseInt(num.textContent)))num.textContent=i+1});seUpdateCount(seCollectSteps());}
function seAddStep(){var list=document.getElementById('se-steps-list');if(!list)return;var idx=list.children.length;var el=seMakeStep({title:'Step '+(idx+1),body:''},idx);list.appendChild(el);seMarkDirty();seUpdateCount(seCollectSteps());el.scrollIntoView({behavior:'smooth',block:'nearest'});}
function seUpdateCount(steps){var el=document.getElementById('se-step-count');if(el)el.textContent=steps.length+' step'+(steps.length!==1?'s':'');}
function seCollectSteps(){var list=document.getElementById('se-steps-list');if(!list)return[];return Array.from(list.children).map(function(div){var ti=div.querySelector('input');var ta=div.querySelector('textarea');return{title:ti?ti.value:'',body:ta?ta.value:''};});}
